mapper.sql:
SELECT DISTINCT #{taxClass_01} taxClass, portfolio_id portfolioId, PORTFOLIO_NAME portfolioName, finprod_id finprodId, FINPROD_ABBR finprodAbbr, FINPROD_MARKET_ID finprodMarketId, '' channelId, '' channelName, tradeId, totleTradeId, trade_Status tradeStatus, ccy, vDate, mDate, seitleDate, interestIncome, dividendIncome, /*红利收入*/ difbetIncome, /* 价差收入*/ interestIncome + dividendIncome + difbetIncome appreciationTax, constructionTax, educationTax, placeeducationTax, waterTrafficTax, constructionTax + educationTax + placeeducationTax + waterTrafficTax additionalTax, Trade_Amt taxTotal, ACCT_NAME actName, taxidenType /*类型*/ FROM ( SELECT TPD.TOTLE_TRADE_ID totleTradeId, TPD.TRADE_ID tradeId, TPD.PS taxidenType, tpa.portfolio_id, ptl.PORTFOLIO_NAME, /*组合名称*/ prd.finprod_id, prd.FINPROD_MARKET_ID, prd.FINPROD_ABBR, TPD.Trade_Amt, tpd.ccy, DATE_FORMAT(TPD.VDATE, '%Y-%m-%d ') vDate, DATE_FORMAT(TPD.MDATE, '%Y-%m-%d ') mDate, DATE_FORMAT(TPD.SETTLE_DATE, '%Y-%m-%d ') seitleDate, IFNULL((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{TAX0102}), 0) interestIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{TAX0202}) dividendIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{TAX0302}) difbetIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0102}) constructionTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0202}) educationTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0302}) placeeducationTax, IFNULL((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = TPD.TRADE_ID AND TFD.FEE_TYPE = #{ALT0402}),0) waterTrafficTax, TPD.TRADE_STATUS, stli.ACCT_NAME, TPD.Finprod_Type, TPD.Finprod_Type2 FROM TRD_PRODUCT_DEAL TPD left join trd_product_deal_add tpa on tpd.trade_id = tpa.trade_id left join fin_product prd on tpd.finprod_id = prd.finprod_id left join stl_pay_orders stl on TPD.TOTLE_TRADE_ID = stl.trade_id left join STL_CAPACCT_INFO stli on (case when stl.ps = #{ps01} then stl.MY_ACCT_NO else stl.COUNTER_ACCT_NO end ) = stli.acct_no left join PTL_PORTFOLIO ptl on tpa.portfolio_id = ptl.portfolio_id where TPD.BUSI_TYPE = #{busiType16} and TPD.Finprod_Type = #{finprodType} and TPD.Finprod_Type2 = #{finprodType2} and tpd.chl_id is null and not exists ( select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = TPD.TRADE_ID )
and TPD.CCY = #{ccy}
and TPD.TRADE_STATUS = #{tradeStatus}
and TPD.FINPROD_ID = #{finprodId}
and TPD.PS = #{taxidenType}
and TPD.TRADE_DATE >= #{vatDateBegin}
and TPD.TRADE_DATE <= #{vatDateEnd}
and tpa.portfolio_id in
#{item}
and TPD.TOTLE_TRADE_ID in
#{item}
) zz1

select #{taxClass_02} taxClass, portfolioId, portfolioName, '' finprodId, '' finprodAbbr, '' finprodMarketId, channelId, channelName, tradeId, totleTradeId, tradeStatus, ccy, vdate, mdate, seitleDate, interestIncome, /*利息收入*/ dividendIncome, /*红利收入*/ difbetIncome, /* 价差收入*/ interestIncome + dividendIncome + difbetIncome appreciationTax, constructionTax, educationTax, placeeducationTax, waterTrafficTax, constructionTax + educationTax + placeeducationTax + waterTrafficTax additionalTax, tradeAmt, actName, taxidenType from( select ad.portfolio_id portfolioId, ptl.portfolio_name portfolioName, f.finprod_market_id channelId, f.finprod_abbr channelName, deal.totle_trade_id totleTradeId, deal.trade_id tradeId, deal.trade_status tradeStatus, deal.finprod_type2, deal.ccy, DATE_FORMAT(deal.vdate, '%Y-%m-%d') vdate, DATE_FORMAT(deal.mdate, '%Y-%m-%d') mdate, DATE_FORMAT(deal.settle_date, '%Y-%m-%d') seitleDate, stli.ACCT_NAME actName, deal.trade_amt tradeAmt, deal.ps taxidenType, IFNULL((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{TAX0102}), 0) interestIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{TAX0202}) dividendIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{TAX0302}) difbetIncome, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0102}) constructionTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0202}) educationTax, (SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0302}) placeeducationTax, IFNULL((SELECT TFD.FEE_AMT FROM TRD_TRADE_FEE_DETAIL TFD WHERE TFD.TRADE_ID = deal.TRADE_ID AND TFD.FEE_TYPE = #{ALT0402}), 0) waterTrafficTax from trd_product_deal deal inner join fin_product f on deal.chl_id = f.finprod_id and f.finprod_type2 = #{finprodType2_F28} left join trd_product_deal_add ad on ad.trade_id = deal.trade_id left join ptl_portfolio ptl on ptl.portfolio_id = ad.portfolio_id left join stl_pay_orders stl on deal.TOTLE_TRADE_ID = stl.trade_id left join STL_CAPACCT_INFO stli on (case when stl.ps = #{ps01} then stl.MY_ACCT_NO else stl.COUNTER_ACCT_NO end ) = stli.acct_no where 1=1 and deal.busi_type = #{busiType16} and deal.Finprod_Type = #{finprodType} and deal.Finprod_Type2 = #{finprodType2} and not exists (select 1 from TRD_PRODUCT_DEAL b where b.P_TRADE_ID = deal.TRADE_ID)
and f.finprod_market_id = #{channelId}
and deal.TRADE_DATE >= #{vatDateBegin}
and deal.TRADE_DATE <= #{vatDateEnd}
and deal.PS = #{taxidenType}
and deal.TRADE_STATUS = #{tradeStatus}
and ad.portfolio_id in
#{item}
) zz2

mapper.select:
select * from (









        UNION ALL



) zz order by seitleDate,channelId

select fin_product.finprod_market_id id, fin_product.finprod_abbr text, CONCAT(IFNULL(fin_product.finprod_id ,''), ',' , IFNULL(fin_product_add.pay_type,'')) object from fin_product left join fin_product_add on fin_product_add.finprod_id = fin_product.finprod_id 1=1 and fin_product.finprod_type2 = #{finprodType2_F28}
AND (fin_product.finprod_market_id LIKE CONCAT('%', CONCAT(#{search}, '%')) OR fin_product.finprod_abbr LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND fin_product.finprod_market_id = #{initValue}
